def twoSum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        need = target - x
        if need in seen:
            return [seen[need], i]
        seen[x] = i

def twoSum(nums, target):
    idx = sorted(range(len(nums)), key=lambda i: nums[i])
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        s = nums[idx[lo]] + nums[idx[hi]]
        if s == target:
            return [idx[lo], idx[hi]]
        if s < target:
            lo += 1
        else:
            hi -= 1
